// The reference shipped inside the package (dist/llms.txt, dist/reference.md,
// generated by cem/reference.js from the manifest) covers every element, so a
// new component cannot ship without appearing in it (#54).
// Requires a prior build; `mise run test` depends on `mise run build`.
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { buildReference, collectElements, loadSupplement } from '../cem/reference.js';

const root = resolve(__dirname, '..');
const manifest = JSON.parse(readFileSync(resolve(root, 'dist/custom-elements.json'), 'utf8'));
const { supplement, snippets } = loadSupplement();
const built = buildReference({ manifest, supplement, snippets, version: '1.2.3' });
const shipped = {
  llms: readFileSync(resolve(root, 'dist/llms.txt'), 'utf8'),
  reference: readFileSync(resolve(root, 'dist/reference.md'), 'utf8'),
};

const registered: string[] = manifest.modules.flatMap((m: { declarations?: { tagName?: string }[] }) =>
  (m.declarations ?? []).filter((d) => d.tagName).map((d) => d.tagName as string),
);

describe('package reference', () => {
  it('has a section and an example for every registered element', () => {
    expect(registered.length).toBeGreaterThan(50);
    for (const tag of registered) {
      const start = shipped.reference.indexOf(`## \`<${tag}>\``);
      expect(start, `reference.md has no section for <${tag}>`).toBeGreaterThanOrEqual(0);
      const next = shipped.reference.indexOf('\n## `<', start + 1);
      const section = shipped.reference.slice(start, next < 0 ? undefined : next);
      expect(section, `<${tag}> has no example`).toMatch(/```html\n[\s\S]+\n```/);
      expect(shipped.llms, `llms.txt does not list <${tag}>`).toContain(`\`<${tag}>\``);
    }
  });

  it('covers the CSS-only parts and patterns too', () => {
    const css = (collectElements(manifest, supplement) as { tag: string; cssOnly: boolean }[]).filter((e) => e.cssOnly);
    expect(css.length).toBeGreaterThan(0);
    for (const e of css) expect(shipped.reference).toContain(`## \`<${e.tag}>\``);
  });

  it('writes every attribute, enum value and event of the manifest', () => {
    for (const mod of manifest.modules) {
      for (const d of mod.declarations ?? []) {
        if (!d.tagName) continue;
        const start = shipped.reference.indexOf(`## \`<${d.tagName}>\``);
        const next = shipped.reference.indexOf('\n## `<', start + 1);
        const section = shipped.reference.slice(start, next < 0 ? undefined : next);
        for (const a of d.attributes ?? []) expect(section, `${d.tagName} ${a.name}`).toContain(`\`${a.name}\``);
        for (const e of d.events ?? []) if (e.name) expect(section, `${d.tagName} ${e.name}`).toContain(`\`${e.name}\``);
      }
    }
  });

  it('is what the generator writes, and llms.txt stays short and points at the full file', () => {
    expect(built.tags.length).toBeGreaterThanOrEqual(registered.length);
    expect(shipped.llms).toContain('@voidable/ui/reference.md');
    expect(shipped.llms).toMatch(/^## Composition rules$/m);
    expect(shipped.llms).toMatch(/^## Conventions$/m);
    expect(shipped.reference.length).toBeGreaterThan(shipped.llms.length);
  });
});
